INSERT INTO `lesson_plan_templates` (`id`, `title`, `subject_id`, `department_id`, `created_by`, `is_system`, `is_active`, `template_data`, `created_at`, `updated_at`) VALUES ('1', 'BSISC Standard 5E Model Template (Mathematics & Science)', '1', '10', '9', '1', '1', '{\"title\": \"Standard 5E Instructional Plan\", \"outcomes\": [{\"sort_order\": 1, \"outcome_text\": \"Demonstrate foundational comprehension of the core concept\"}, {\"sort_order\": 2, \"outcome_text\": \"Execute practical problem-solving using appropriate methods\"}], \"activities\": [{\"stage\": \"introduction\", \"sort_order\": 1, \"duration_minutes\": 5, \"student_activities\": \"Engage & Discuss\", \"teacher_activities\": \"Hook & Recall\"}, {\"stage\": \"presentation\", \"sort_order\": 2, \"duration_minutes\": 15, \"student_activities\": \"Listen & Note\", \"teacher_activities\": \"Direct Instruction\"}, {\"stage\": \"guided_practice\", \"sort_order\": 3, \"duration_minutes\": 15, \"student_activities\": \"Solve together\", \"teacher_activities\": \"Facilitate Pair Work\"}, {\"stage\": \"conclusion\", \"sort_order\": 4, \"duration_minutes\": 10, \"student_activities\": \"Record homework\", \"teacher_activities\": \"Summary & Homework\"}], \"teaching_method\": \"Engage, Explore, Explain, Elaborate, Evaluate\", \"teaching_materials\": \"Whiteboard, Digital Projector, Textbook\"}', '2026-09-08 15:03:27', '2026-09-09 12:03:29');
INSERT INTO `notices` (`id`, `title_bn`, `title_en`, `content_bn`, `content_en`, `category`, `priority`, `target_audience`, `attachment_path`, `attachment_name`, `is_pinned`, `is_published`, `publish_date`, `expiry_date`, `created_by`, `created_at`, `updated_at`) VALUES ('1', 'জরুরি: প্রথম সাময়িক পরীক্ষার পাঠ পরিকল্পনা জমাদানের শেষ সময়সীমা', 'URGENT: Term 1 Lesson Plan Submission Deadline for Teachers', 'সকল সম্মানিত শিক্ষকবৃন্দকে জানানো যাচ্ছে যে, ২০২৬ শিক্ষাবর্ষের ১ম সাময়িক পরীক্ষার জন্য সকল নির্ধারিত বিষয়ের পূর্ণাঙ্গ পাঠ পরিকল্পনা আগামী ১৫ সেপ্টেম্বর ২০২৬ এর মধ্যে সিস্টেমে জমা দেওয়া বাধ্যতামূলক। পাঠ পরিকল্পনায় শিক্ষাক্রমের শিখনফল এবং ব্লুমস ট্যাক্সোনমি স্তর যথাযথভাবে উল্লেখ থাকতে হবে।', 'All esteemed faculty members of BSISC (EIIN: 133988) are hereby requested to submit their comprehensive lesson plans for Term 1 by September 15, 2026. Please ensure all pedagogical outcomes, activity timings, and Bloom\'s Taxonomy domains are thoroughly mapped.', 'urgent', 'urgent', 'teachers', NULL, NULL, '1', '1', '2026-09-08 12:04:14', '2026-10-09 12:04:14', '2', '2026-09-08 15:03:27', '2026-09-09 12:04:14');
INSERT INTO `notices` (`id`, `title_bn`, `title_en`, `content_bn`, `content_en`, `category`, `priority`, `target_audience`, `attachment_path`, `attachment_name`, `is_pinned`, `is_published`, `publish_date`, `expiry_date`, `created_by`, `created_at`, `updated_at`) VALUES ('2', 'পাঠ পরিকল্পনায় ব্লুমস ট্যাক্সোনমি ও অ্যাক্টিভিটি টাইম ক্যালকুলেটর ব্যবহারের নির্দেশিকা', 'Guidelines on Bloom\'s Taxonomy & Activity Duration Calculator', 'সমন্বয়ক পরিষদ কর্তৃক অনুমোদিত নতুন মানদণ্ড অনুযায়ী প্রতিটি পাঠ পরিকল্পনায় ওয়ার্ম-আপ, শিক্ষক উপস্থাপন, দলগত কাজ এবং মূল্যায়নের সময়সীমা নির্ধারিত মোট সময়ের সাথে শতভাগ সামঞ্জস্যপূর্ণ হতে হবে। সিস্টেমের লাইভ টাইম ক্যালকুলেটর ব্যবহার করার পরামর্শ দেওয়া হচ্ছে।', 'In accordance with Academic Council standards, all lesson plans must balance duration across Warm-up, Teacher Presentation, Guided Practice, and Plenary. Teachers are instructed to utilize the system\'s real-time duration calculator to eliminate timing discrepancies.', 'curriculum', 'high', 'teachers', NULL, NULL, '1', '1', '2026-09-07 12:04:14', '2026-11-08 12:04:14', '1', '2026-09-08 15:03:27', '2026-09-09 12:04:14');
INSERT INTO `notices` (`id`, `title_bn`, `title_en`, `content_bn`, `content_en`, `category`, `priority`, `target_audience`, `attachment_path`, `attachment_name`, `is_pinned`, `is_published`, `publish_date`, `expiry_date`, `created_by`, `created_at`, `updated_at`) VALUES ('3', 'শিক্ষক ও সমন্বয়কদের নিয়ে বিশেষ একাডেমিক মতবিনিময় সভা', 'Special Academic Review & Coordination Meeting with Principal', 'আগামীকাল বেলা ১২:০০ ঘটিকায় কলেজ সম্মেলন কক্ষে অধ্যক্ষ মহোদয়ের সভাপতিত্বে বিশেষ একাডেমিক সমন্বয় সভা অনুষ্ঠিত হবে। সকল বিভাগীয় প্রধান ও সমন্বয়কদের ডিজিটাল পাঠ পরিকল্পনা অগ্রগতি প্রতিবেদন সঙ্গে আনার জন্য অনুরোধ করা হলো।', 'A mandatory curriculum review meeting will be held tomorrow at 12:00 PM in the College Conference Room presided over by the Principal. All Department Heads and Coordinators are requested to bring their current lesson plan approval and review status reports.', 'academic', 'high', 'coordinators', NULL, NULL, '0', '1', '2026-09-09 06:04:14', '2026-09-16 12:04:14', '2', '2026-09-08 15:03:27', '2026-09-09 12:04:14');
INSERT INTO `notices` (`id`, `title_bn`, `title_en`, `content_bn`, `content_en`, `category`, `priority`, `target_audience`, `attachment_path`, `attachment_name`, `is_pinned`, `is_published`, `publish_date`, `expiry_date`, `created_by`, `created_at`, `updated_at`) VALUES ('4', 'বিএসআইএসসি ডিজিটাল পাঠ পরিকল্পনা ব্যবস্থাপনা প্ল্যাটফর্ম ১.০ চালু', 'BSISC Digital Lesson Plan Management System v1.0 Launched', 'বারিধারা স্কলার্স ইন্টারন্যাশনাল স্কুল অ্যান্ড কলেজের (স্কুল কোড: ১২৪২, কলেজ কোড: ১৭৬০) সকল সম্মানিত শিক্ষক, সমন্বয়ক ও প্রশাসনের জন্য অত্যাধুনিক ডিজিটাল পাঠ পরিকল্পনা ও পর্যবেক্ষণ প্ল্যাটফর্ম আনুষ্ঠানিকভাবে চালু হয়েছে।', 'We are pleased to announce the full operational rollout of the BSISC Digital Lesson Plan System for Baridhara Scholars\' International School & College (DOHS Baridhara, Dhaka Cantonment). This system empowers dynamic curriculum design, multi-stage reviews, calendar scheduling, and instant DomPDF reporting.', 'general', 'normal', 'all', NULL, NULL, '0', '1', '2026-09-06 12:04:14', '2026-12-08 12:04:14', '1', '2026-09-08 15:03:27', '2026-09-09 12:04:14');
INSERT INTO `notices` (`id`, `title_bn`, `title_en`, `content_bn`, `content_en`, `category`, `priority`, `target_audience`, `attachment_path`, `attachment_name`, `is_pinned`, `is_published`, `publish_date`, `expiry_date`, `created_by`, `created_at`, `updated_at`) VALUES ('5', 'বিজ্ঞান বিভাগের ল্যাব ক্লাস পরিকল্পনা ও সুরক্ষা নীতিমালা সংযুক্তি', 'Science Department: Practical Lab Safety Protocol in Lesson Plans', 'নবম ও দশম শ্রেণীর পদার্থ, রসায়ন এবং জীববিজ্ঞান বিষয়ের শিক্ষকদের ব্যবহারিক ক্লাসের পাঠ পরিকল্পনায় বিশেষ সুরক্ষা নির্দেশিকা ও প্রয়োজনীয় রাসায়নিক/যন্ত্রপাতির তালিকা সংযুক্ত করার নির্দেশ দেওয়া হচ্ছে।', 'Science faculty members teaching Classes IX-XII are required to explicitly attach laboratory safety measures and required apparatus checklists in Step 3 (Activities & Resources) of their lesson plans.', 'curriculum', 'normal', 'teachers', NULL, NULL, '0', '1', '2026-09-05 12:04:14', '2026-10-24 12:04:14', '1', '2026-09-08 15:03:27', '2026-09-09 12:04:14');
INSERT INTO `notices` (`id`, `title_bn`, `title_en`, `content_bn`, `content_en`, `category`, `priority`, `target_audience`, `attachment_path`, `attachment_name`, `is_pinned`, `is_published`, `publish_date`, `expiry_date`, `created_by`, `created_at`, `updated_at`) VALUES ('7', 'আগামীকাল সকাল ৯টায় জরুরি শিক্ষক পরিষদ সভা', 'Emergency Teachers Council Meeting Tomorrow at 9:00 AM', 'সকল শ্রদ্ধেয় শিক্ষক-শিক্ষিকাদের আগামীকালের জরুরি সভায় উপস্থিত থাকতে অনুরোধ করা হচ্ছে।', 'All respected teachers are requested to attend the emergency meeting tomorrow.', 'urgent', 'urgent', 'teachers', NULL, NULL, '1', '1', '2026-09-09 00:31:49', NULL, '1', '2026-09-09 00:31:49', '2026-09-09 00:31:49');
