INSERT INTO `form_schemas` (`id`, `form_type`, `title`, `slug`, `description`, `instructions`, `is_default`, `is_active`, `post_payment_action`, `layout_style`, `submission_count`, `deadline`, `schema_data`, `created_by`, `created_at`, `updated_at`) VALUES ('1', 'admission', 'স্ট্যান্ডার্ড শিক্ষার্থী ভর্তি আবেদন ফরম (Standard Admission Form)', 'admission', 'Official BSISC Dynamic Admission Application Form Schema with live candidate view preview and multi-step validation.', NULL, '1', '1', 'application_voucher', 'wizard', '2', NULL, '{\"title\": \"স্ট্যান্ডার্ড শিক্ষার্থী ভর্তি আবেদন ফরম (Standard Admission Form)\", \"sections\": [{\"id\": \"sec_student_identity\", \"icon\": \"User\", \"order\": 1, \"fields\": [{\"id\": \"f_school_version\", \"type\": \"select\", \"options\": [{\"value\": \"bangla\", \"label_bn\": \"বাংলা ভার্সন\", \"label_en\": \"Bangla Version\"}, {\"value\": \"english\", \"label_bn\": \"ইংলিশ ভার্সন\", \"label_en\": \"English Version\"}], \"visible\": true, \"category\": \"STUDENT_INFO\", \"grid_col\": 3, \"label_bn\": \"বাংলা ভার্সন / ইংলিশ ভার্সন\", \"label_en\": \"School Version\", \"required\": true, \"field_key\": \"school_version\", \"profile_sync\": \"schoolVersion\"}, {\"id\": \"f_school_shift\", \"type\": \"select\", \"options\": [{\"value\": \"morning\", \"label_bn\": \"প্রভাতি শিফট\", \"label_en\": \"Morning Shift (প্রভাতি)\"}, {\"value\": \"day\", \"label_bn\": \"দিবা শিফট\", \"label_en\": \"Day Shift (দিবা)\"}], \"visible\": true, \"category\": \"STUDENT_INFO\", \"grid_col\": 3, \"label_bn\": \"প্রভাতি বা দিবা শিফট\", \"label_en\": \"School Shift\", \"required\": true, \"field_key\": \"school_shift\", \"profile_sync\": \"schoolShift\"}, {\"id\": \"f_applicable_quota\", \"type\": \"select\", \"options\": [{\"value\": \"general\", \"label_bn\": \"সাধারণ কোটা\", \"label_en\": \"General (সাধারণ)\"}, {\"value\": \"freedom_fighter\", \"label_bn\": \"মুক্তিযোদ্ধা কোটা\", \"label_en\": \"Freedom Fighter (মুক্তিযোদ্ধা)\"}, {\"value\": \"defense\", \"label_bn\": \"প্রতিরক্ষা কোটা\", \"label_en\": \"Army / Defense Personnel (প্রতিরক্ষা কোটা)\"}, {\"value\": \"staff_child\", \"label_bn\": \"শিক্ষক/কর্মচারী সন্তান\", \"label_en\": \"Teacher / Staff Child (শিক্ষক/কর্মচারী সন্তান)\"}, {\"value\": \"disability\", \"label_bn\": \"প্রতিবন্ধী কোটা\", \"label_en\": \"Disability / Special Needs (প্রতিবন্ধী)\"}], \"visible\": true, \"category\": \"STUDENT_INFO\", \"grid_col\": 3, \"label_bn\": \"প্রযোজ্য কোটা নির্বাচন করুন\", \"label_en\": \"Applicable Quota\", \"required\": true, \"field_key\": \"applicable_quota\", \"profile_sync\": \"quota\"}, {\"id\": \"f_student_name_en\", \"type\": \"text\", \"visible\": true, \"category\": \"STUDENT_INFO\", \"grid_col\": 3, \"label_bn\": \"ডিজিটাল জন্ম সনদ অনুযায়ী বড় হাতের অক্ষরে লিখুন\", \"label_en\": \"Student Full Name (English)\", \"required\": true, \"field_key\": \"student_name_en\", \"placeholder\": \"CANDIDATE FULL NAME IN CAPITAL LETTERS\", \"profile_sync\": \"name\"}, {\"id\": \"f_student_name_bn\", \"type\": \"text\", \"visible\": true, \"category\": \"STUDENT_INFO\", \"grid_col\": 3, \"label_bn\": \"বাংলায় সঠিক বানান লিখুন\", \"label_en\": \"Student Name (Bangla)\", \"required\": false, \"field_key\": \"student_name_bn\", \"placeholder\": \"শিক্ষার্থীর পূর্ণ নাম বাংলায়\", \"profile_sync\": \"nameBangla\"}, {\"id\": \"f_dob\", \"type\": \"date\", \"visible\": true, \"category\": \"STUDENT_INFO\", \"grid_col\": 3, \"label_bn\": \"ডিজিটাল জন্ম সনদ অনুযায়ী তারিখ নির্বাচন করুন\", \"label_en\": \"Date of Birth\", \"required\": true, \"field_key\": \"dob\", \"profile_sync\": \"birthDate\"}, {\"id\": \"f_birth_cert_no\", \"type\": \"text\", \"visible\": true, \"category\": \"STUDENT_INFO\", \"grid_col\": 3, \"label_bn\": \"১৭ ডিজিটের অনলাইন জন্ম নিবন্ধন নম্বর লিখুন\", \"label_en\": \"Digital Birth Certificate No\", \"required\": true, \"field_key\": \"birth_cert_no\", \"placeholder\": \"17-digit Online Birth Registration Number\", \"profile_sync\": \"birthCertificateNo\"}